{
  "findings": [
    {
      "check_id": "CKV2_AWS_11",
      "title": "Ensure VPC flow logging is enabled in all VPCs",
      "resource": "aws_vpc.changeme_aws_vpc_simple",
      "severity": "MEDIUM",
      "explanation": "The VPC does not have flow logs configured, which prevents monitoring and troubleshooting of network traffic for security analysis."
    },
    {
      "check_id": "CKV2_AWS_12",
      "title": "Ensure the default security group of every VPC restricts all traffic",
      "resource": "aws_vpc.changeme_aws_vpc_simple",
      "severity": "MEDIUM",
      "explanation": "The default security group associated with this VPC allows all inbound and outbound traffic by default, creating a potential attack surface if resources are accidentally attached to it."
    }
  ],
  "patched_code": "resource "aws_vpc" "changeme_aws_vpc_simple" {
  cidr_block = "10.1.0.0/16"
}

# Enable VPC Flow Logs
resource "aws_cloudwatch_log_group" "vpc_flow_logs" {
  name              = "/aws/vpc/${aws_vpc.changeme_aws_vpc_simple.id}/flow-logs"
  retention_in_days = 30
}

resource "aws_iam_role" "vpc_flow_logs_role" {
  name = "vpc-flow-logs-role-${aws_vpc.changeme_aws_vpc_simple.id}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "vpc-flow-logs.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy" "vpc_flow_logs_policy" {
  name = "vpc-flow-logs-policy-${aws_vpc.changeme_aws_vpc_simple.id}"
  role = aws_iam_role.vpc_flow_logs_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "logs:DescribeLogGroups",
          "logs:DescribeLogStreams"
        ]
        Effect   = "Allow"
        Resource = "*"
      }
    ]
  })
}

resource "aws_flow_log" "example" {
  iam_role_arn    = aws_iam_role.vpc_flow_logs_role.arn
  log_destination = aws_cloudwatch_log_group.vpc_flow_logs.arn
  traffic_type    = "ALL"
  vpc_id          = aws_vpc.changeme_aws_vpc_simple.id
}

# Restrict Default Security Group
resource "aws_default_security_group" "default" {
  vpc_id = aws_vpc.changeme_aws_vpc_simple.id

  # No ingress or egress rules defined means all traffic is denied
}",
  "fix_summary": "Added CloudWatch Log Group, IAM Role, and Flow Log resource to enable VPC flow logging. Added an aws_default_security_group resource with no ingress/egress rules to explicitly deny all traffic on the default security group."
}
